const trigger = $('WhatsApp Trigger').first().json || {};
const msg = trigger.messages?.[0] || {};
const isImage = msg.type === 'image';
const media = isImage ? (msg.image || {}) : (msg.document || {});
const inputItem = $input.item;
const binary = { ...(inputItem.binary || {}) };
const binaryMeta = binary.data || {};

const mimeType = String(
  media.mime_type ||
  binaryMeta.mimeType ||
  (isImage ? 'image/jpeg' : 'application/pdf')
);

let fileName = String(media.filename || binaryMeta.fileName || '').trim();
if (!fileName) {
  const safeId = String(msg.id || media.id || Date.now())
    .replace(/[^a-zA-Z0-9_-]/g, '_')
    .slice(-80);

  let ext = 'bin';
  if (mimeType === 'application/pdf') ext = 'pdf';
  else if (mimeType === 'image/jpeg') ext = 'jpg';
  else if (mimeType === 'image/png') ext = 'png';
  else if (mimeType === 'image/webp') ext = 'webp';
  else if (mimeType === 'image/gif') ext = 'gif';

  fileName = `${isImage ? 'imagen' : 'documento'}-${safeId}.${ext}`;
}

if (binary.data) {
  binary.data = {
    ...binary.data,
    fileName,
    mimeType
  };
}

const caption = String(media.caption || '').trim();

return {
  json: {
    clientId: trigger.metadata?.phone_number_id || '',
    chatId: trigger.contacts?.[0]?.wa_id || msg.from || '',
    contactName: trigger.contacts?.[0]?.profile?.name || '',
    phoneNumber: trigger.contacts?.[0]?.wa_id || msg.from || '',
    content: caption,
    messageId: msg.id || '',
    sender: 'user',
    status: 'received',
    timestamp: Number(msg.timestamp || 0) > 0 ? new Date(Number(msg.timestamp) * 1000).toISOString() : new Date().toISOString(),
    mediaType: isImage ? 'image' : 'document',
    mimeType,
    fileName,
    mediaId: String(media.id || ''),
    hasCaption: caption.length > 0,
    sourceTimestamp: Number(msg.timestamp || 0),
    bufferEligible: caption.length > 0
  },
  binary
};

