parameters.jsCode:
const trigger = $('WhatsApp Trigger').first().json || {};
const msg = trigger.messages?.[0] || {};
const clientId = String(trigger.metadata?.phone_number_id || '');
const chatId = String(trigger.contacts?.[0]?.wa_id || msg.from || '');
const currentMessageId = String(msg.id || '');

const rawSourceTimestamp = Number(msg.timestamp || 0);
const currentSourceTimestamp = Number.isFinite(rawSourceTimestamp) && rawSourceTimestamp > 0
  ? rawSourceTimestamp
  : Math.floor(Date.now() / 1000);

const currentContent = String(
  msg.type === 'text'
    ? (msg.text?.body || '')
    : (msg.image?.caption || msg.document?.caption || '')
).trim();

const storedAt = new Date().toISOString();

return {
  json: {
    ...$json,
    bufferKey: `${clientId}:${chatId}`,
    bufferItemKey: `${clientId}:${chatId}:${currentMessageId}`,
    clientId,
    chatId,
    currentMessageId,
    messageId: currentMessageId,
    content: currentContent,
    currentSourceTimestamp,
    sourceTimestamp: currentSourceTimestamp,
    storedAt,
    updatedAt: storedAt
  }
};

const rows = $input.all().map(i => i.json || {});
const prep = $('Preparar buffer mensajes').first().json || {};
const latest = $('Buscar último mensaje elegible').first().json || {};

const seen = new Set();
const parts = [];

for (const row of rows) {
  const id = String(row.messageId || '');
  if (id && seen.has(id)) continue;
  if (id) seen.add(id);

  const content = String(row.content || '').trim();
  if (content) parts.push(content);
}

let bufferedMessage = parts.join('\n').trim();

// Fallback defensivo: el mensaje actual nunca debe perderse.
if (!bufferedMessage) {
  bufferedMessage = String(prep.content || '').trim();
}

return [{
  json: {
    ...prep,
    bufferedMessage,
    bufferedMessageCount: parts.length || (bufferedMessage ? 1 : 0),
    bufferKey: prep.bufferKey,
    lastProcessedSourceTimestamp: Number(latest.sourceTimestamp || prep.currentSourceTimestamp || 0),
    lastProcessedStoredAt: String(latest.storedAt || prep.storedAt || new Date().toISOString()),
    lastProcessedMessageId: String(latest.messageId || prep.currentMessageId || ''),
    processedAt: new Date().toISOString()
  }
}];

const proofRule = `# COMPROBANTES DE SEÑA

Si el cliente indica que hizo una transferencia o envía un comprobante, nunca confirmes el pago ni la reserva automáticamente. Si corresponde acusar recibo, indicá únicamente que queda pendiente de validación por el equipo. El estado real de la seña sólo puede ser validado por Foodie.`;
return [{ json: { ...$json, restaurantInstructions: `${$json.restaurantInstructions}\n\n${proofRule}` } }];

const prepared = $('Preparar adjunto para PupuIA').first();
const file = prepared.binary?.data || {};
const rawSize = file.fileSize ?? 0;
const units = { b: 1, kb: 1024, mb: 1024 * 1024, gb: 1024 * 1024 * 1024 };
const match = String(rawSize).trim().toLowerCase().match(/^([\d.]+)\s*(b|kb|mb|gb)?$/);
const size = match ? Math.floor(Number(match[1]) * (units[match[2] || 'b'] || 1)) : Number(rawSize);
return { json: { ...prepared.json, requestId: $json.requestId, size }, binary: prepared.binary };
